"use client";

import Image from "next/image";
import { useState } from "react";

type Props = { id: string; title: string; playLabel?: string };

/**
 * YouTube Shorts facade: renders the thumbnail in a 9:16 frame and only
 * injects the iframe after the visitor presses play — keeps the homepage
 * free of third-party JS until it is actually needed.
 */
export function VideoShort({ id, title, playLabel = "Play video" }: Props) {
  const [playing, setPlaying] = useState(false);
  const thumb = `https://i.ytimg.com/vi/${id}/oar2.jpg`; // vertical thumbnail; falls back gracefully

  return (
    <div className="group relative aspect-[9/16] w-full overflow-hidden bg-plum-100">
      {playing ? (
        <iframe
          src={`https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1&playsinline=1`}
          title={title}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          allowFullScreen
          loading="lazy"
          className="absolute inset-0 h-full w-full"
        />
      ) : (
        <button
          type="button"
          onClick={() => setPlaying(true)}
          aria-label={`${playLabel}: ${title}`}
          className="absolute inset-0 h-full w-full text-left focus-visible:outline-plum-500"
        >
          <Image
            src=""
            alt=""
            fill
            sizes="(max-width: 640px) 80vw, (max-width: 1024px) 40vw, 22vw"
            className="object-cover transition-transform duration-[1400ms] ease-luxe group-hover:scale-105"
            loading="lazy"
            unoptimized
          />
          <span className="absolute inset-0 bg-gradient-to-t from-plum-900/60 via-transparent to-transparent" />
          <span className="absolute left-1/2 top-1/2 flex h-16 w-16 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-cream/80 bg-cream/15 text-cream backdrop-blur-sm transition-all duration-500 ease-luxe group-hover:scale-110 group-hover:bg-cream group-hover:text-plum-700">
            <svg viewBox="0 0 24 24" className="ml-1 h-5 w-5" fill="currentColor" aria-hidden="true">
              <path d="M8 5.5v13l11-6.5z" />
            </svg>
          </span>
          <span className="absolute inset-x-0 bottom-0 p-5 font-serif text-lg italic text-cream">{title}</span>
        </button>
      )}
    </div>
  );
}
